import {
  appendFileSync,
  existsSync,
  mkdirSync,
  readFileSync,
  rmSync,
  statSync,
  writeFileSync,
} from "node:fs";
import { execFileSync } from "node:child_process";
import path from "node:path";
import { setTimeout as delay } from "node:timers/promises";

const markerToStatus = new Map([
  [" ", "ready"],
  ["~", "in-progress"],
  ["!", "blocked"],
  ["x", "done"],
]);
const validSources = new Set(["claude-code", "github-copilot", "codex", "manual"]);
const logHeader = [
  "<!-- Generated by scripts/log-task-status.mjs. Do not edit entries manually. -->",
  "# Agent Task Status History",
  "",
  "This is an audit trail of observed task status changes, not approval or evidence.",
  "",
  "| Time (UTC) | Task | Previous | Current | Detected by |",
  "| --- | --- | --- | --- | --- |",
  "",
].join("\n");

function parseArguments(argumentsList) {
  const options = { root: process.cwd(), source: undefined };

  for (let index = 0; index < argumentsList.length; index += 1) {
    const argument = argumentsList[index];
    if (argument === "--root") {
      options.root = argumentsList[++index];
    } else if (argument === "--source") {
      options.source = argumentsList[++index];
    } else {
      throw new Error(`Unknown argument: ${argument}`);
    }
  }

  if (!options.root || !options.source || !validSources.has(options.source)) {
    throw new Error("Use --root [path] and --source claude-code|github-copilot|codex|manual.");
  }

  options.root = path.resolve(options.root);
  return options;
}

function parseTaskStatuses(content) {
  const statuses = new Map();
  let currentTaskId;

  for (const line of content.split(/\r?\n/)) {
    if (line.startsWith("## ")) {
      const heading = /^## (T-\d+)(?:\s|$)/.exec(line);
      currentTaskId = heading?.[1];
      if (!currentTaskId) {
        continue;
      }

      if (statuses.has(currentTaskId)) {
        throw new Error(`Duplicate task heading: ${currentTaskId}`);
      }
      statuses.set(currentTaskId, undefined);
      continue;
    }

    const status = /^Stav:\s*\[([ ~!x])\](?:\s|$)/.exec(line);
    if (!currentTaskId || !status) {
      continue;
    }
    if (statuses.get(currentTaskId) !== undefined) {
      throw new Error(`Duplicate status for ${currentTaskId}`);
    }

    statuses.set(currentTaskId, markerToStatus.get(status[1]));
  }

  for (const [taskId, status] of statuses) {
    if (!status) {
      throw new Error(`Missing or invalid status for ${taskId}`);
    }
  }

  return statuses;
}

// Stav úkolů v posledním commitu aktuální větve, nebo null mimo git
// (případně když TASKS.md v HEAD není nebo nejde přečíst). Přepnutí větve,
// pull ani merge pak nezapíšou falešný přechod: pracovní kopie se rovná
// HEAD, takže se nic nezměnilo.
function readCommittedStatuses(root) {
  let content;
  try {
    content = execFileSync("git", ["-C", root, "show", "HEAD:./TASKS.md"], {
      encoding: "utf8",
      stdio: ["ignore", "pipe", "ignore"],
    });
  } catch {
    return null;
  }
  try {
    return parseTaskStatuses(content);
  } catch {
    return null;
  }
}

function readLatestStatuses(logPath) {
  const latestStatuses = new Map();
  if (!existsSync(logPath)) {
    return latestStatuses;
  }

  const rowPattern = /^\| [^|]+ \| (T-\d+) \| (?:new|ready|in-progress|blocked|done) \| (new|ready|in-progress|blocked|done) \| [a-z-]+ \|$/;
  for (const line of readFileSync(logPath, "utf8").split(/\r?\n/)) {
    const row = rowPattern.exec(line);
    if (row) {
      latestStatuses.set(row[1], row[2]);
    }
  }
  return latestStatuses;
}

async function acquireLock(lockPath) {
  const deadline = Date.now() + 5000;

  while (Date.now() < deadline) {
    try {
      mkdirSync(lockPath);
      return;
    } catch (error) {
      if (error.code !== "EEXIST") {
        throw error;
      }

      try {
        if (Date.now() - statSync(lockPath).mtimeMs > 30000) {
          rmSync(lockPath, { recursive: true, force: true });
          continue;
        }
      } catch (statError) {
        if (statError.code !== "ENOENT") {
          throw statError;
        }
      }
      await delay(50);
    }
  }

  throw new Error("Timed out waiting for the task status log lock.");
}

async function recordTaskStatusChanges({ root, source }) {
  const tasksPath = path.join(root, "TASKS.md");
  const logPath = path.join(root, "LOGS.md");
  const lockPath = path.join(root, ".task-status-log.lock");
  if (!existsSync(tasksPath)) {
    throw new Error(`TASKS.md was not found in ${root}`);
  }

  const currentStatuses = parseTaskStatuses(readFileSync(tasksPath, "utf8"));
  const committedStatuses = readCommittedStatuses(root);
  mkdirSync(root, { recursive: true });
  await acquireLock(lockPath);

  try {
    if (!existsSync(logPath)) {
      writeFileSync(logPath, logHeader, "utf8");
    }

    const latestStatuses = readLatestStatuses(logPath);
    const timestamp = new Date().toISOString();
    const entries = [];

    for (const [taskId, currentStatus] of currentStatuses) {
      const loggedStatus = latestStatuses.get(taskId);
      let previousStatus;
      if (committedStatuses) {
        // V gitu: zapisuje se jen necommitnutá změna proti HEAD, předchozí
        // stav je ten z posledního commitu větve.
        const committedStatus = committedStatuses.get(taskId);
        if (committedStatus === currentStatus || loggedStatus === currentStatus) {
          continue;
        }
        previousStatus = committedStatus ?? "new";
      } else {
        previousStatus = loggedStatus ?? "new";
        if (previousStatus === currentStatus) {
          continue;
        }
      }
      entries.push(`| ${timestamp} | ${taskId} | ${previousStatus} | ${currentStatus} | ${source} |`);
    }

    if (entries.length > 0) {
      appendFileSync(logPath, `${entries.join("\n")}\n`, "utf8");
    }
  } finally {
    rmSync(lockPath, { recursive: true, force: true });
  }
}

try {
  await recordTaskStatusChanges(parseArguments(process.argv.slice(2)));
} catch (error) {
  process.stderr.write(`${error.message}\n`);
  process.exitCode = 1;
}